// slot and skip declined Tasks, which only the Watch checks again.
func (s *Service) refillQueuedTasks(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, watch bool) (int, error) {
	admitted := 0
	home, err := s.homePath()
	if err != nil {
		return admitted, err
	}
	declines, err := db.QueuedTaskDeclines(ctx, project.ID)
	if err != nil {
		return admitted, err
	}
	budget := -1
	if !watch {
		active, err := db.ActiveWorkerCount(ctx, project.ID)
		if err != nil {
			return admitted, err
		}
		budget = max(cfg.Defaults.MaxWorkers-active, 0)
	}
	attempted := make(map[int64]bool)
	for {
		active, err := db.ActiveWorkerCount(ctx, project.ID)
		if err != nil {
			return admitted, err
		}
		full := active >= cfg.Defaults.MaxWorkers
		taskIDs, err := db.QueuedTaskIDs(ctx, project.ID)
		if err != nil {
			return admitted, err
		}
		launched := false
		for _, taskID := range taskIDs {
			if attempted[taskID] {
				continue
			}
			if decline, found := declines[taskID]; found && (!watch || time.Since(decline.CheckedAt) < queuedDeclineRecheck) {
				continue
			}
			queued, err := db.TaskByID(ctx, project.ID, taskID)
			if err != nil {
				return admitted, err
			}
			if queued.State != store.StateQueued {
				continue
			}
			plan, err := queued.AdmittedPlan()
			if err != nil {
				return admitted, admittedPlanFailure(err)
			}
			if plan == nil {
				continue
			}
			unmet, err := db.UnmetTaskDependencies(ctx, project.ID, plan.Dependencies)
			if err != nil {
				return admitted, err
			}
			if len(unmet) > 0 {
				for _, dependency := range plan.Dependencies {
					predecessor, taskErr := db.Task(ctx, project.ID, dependency.TaskID)
					if taskErr != nil {
						return admitted, taskErr
					}
					if predecessor.State != store.StateFailed && predecessor.State != store.StateLost && predecessor.State != store.StateTornDown {
						continue
					}
					ready, readyErr := db.UnmetTaskDependencies(ctx, project.ID, []dispatch.Dependency{dependency})
					if readyErr != nil {
						return admitted, readyErr
					}
					if len(ready) == 0 {
						continue
					}
					origin := fmt.Sprintf("dependency:%s:%s:%s", taskIDString(queued.Seq), dependency.TaskID, dependency.Milestone)
					_, decisionErr := db.RaiseDecision(ctx, store.DecisionRequest{
						ProjectID: project.ID, TaskID: queued.ID, Origin: origin, Kind: "dependency",
						Question: fmt.Sprintf("Prerequisite %s for queued Task %s is %s and cannot satisfy %s. Cancel the queued Task, or drop this prerequisite and run it?", dependency.TaskID, taskIDString(queued.Seq), predecessor.State, dependency.Milestone),
						Options:  []string{"cancel", "drop-prerequisite-and-run"},
					})
					if decisionErr != nil {
						return admitted, decisionErr
					}
				}
				continue
			}
			if full || budget == 0 {
				continue
			}
