func (s *Service) deliverNotices(ctx context.Context, db *store.DB, project store.Project) error {
	return s.deliverNoticesWithSnapshot(ctx, db, project, nil)
}

func (s *Service) deliverNoticesWithSnapshot(ctx context.Context, db *store.DB, project store.Project, suppliedSnapshot *herdr.Snapshot) error {
	if project.IsParked() {
		return nil
	}
	if suppliedSnapshot == nil {
		var err error
		snapshot, err := s.snapshot(ctx)
		if err != nil {
			return err
		}
		suppliedSnapshot = &snapshot
	}
	snapshot := *suppliedSnapshot
	if project.HerdrWorkspaceID != "" {
		workspaceFound := false
		for _, workspace := range snapshot.Workspaces {
			if workspace.WorkspaceID == project.HerdrWorkspaceID {
				workspaceFound = true
				break
			}
		}
		if !workspaceFound {
			for _, pane := range snapshot.Panes {
				if pane.WorkspaceID == project.HerdrWorkspaceID {
					workspaceFound = true
					break
				}
			}
		}
		if !workspaceFound {
			return nil
		}
	}
	if err := s.raiseNoticeDecisions(ctx, db, project); err != nil {
		return err
	}
	if err := db.ReleaseExpiredDeliveryClaims(ctx, currentTime()-deliveryClaimTimeout.Milliseconds()); err != nil {
		return err
	}
	if _, err := s.raiseExpiredMessageDeliveryNotices(ctx, db, project); err != nil {
		return err
	}
	if err := raiseDelayedNoticeAlert(ctx, db, project); err != nil {
		return err
	}
	notices, err := db.UndeliveredNotices(ctx, project.ID)
	if err != nil {
		return err
	}
	if len(notices) == 0 {
		lastNotification, err := db.LastNoticeNotification(ctx, project.ID)
		if err != nil || lastNotification == 0 {
			return err
		}
		if project.HerdrWorkspaceID != "" {
			if _, err := s.herdrCall(ctx, "workspace.report_metadata", map[string]any{"workspace_id": project.HerdrWorkspaceID, "source": "posse", "tokens": map[string]string{"posse": ""}}); err != nil {
				return err
			}
		}
		return db.RecordNoticeNotification(ctx, project.ID, 0)
	}
	lastNotification, err := db.LastNoticeNotification(ctx, project.ID)
	if err != nil {
		return err
	}
	if len(snapshot.Panes) == 0 {
		snapshot, err = s.snapshot(ctx)
		if err != nil {
			return err
		}
	}
	lead, found := findAppPane(snapshot.Panes, project.LeadPaneID, project.LeadLabel)
	delivery := ""
	if found && lead.Agent != "" {
		delivery = s.leadNoticeDelivery(project, lead.Agent)
		if lead.Tokens["posse_attached"] == "true" && extensionOwnsNotices(delivery) {
			delivery = config.NoticeDeliveryPrompt
		}
	}
	// An extension or plugin can be lost while its Lead keeps running, for
	// example when Herdr resumes the Lead without Posse's launch arguments.
	monitorsReceiver := extensionOwnsNotices(delivery) || lead.Agent == "claude" && delivery == config.NoticeDeliveryWatch
	idleLead := lead.AgentStatus == "idle" || lead.AgentStatus == "done"
	if monitorsReceiver && (idleLead || lead.Agent == "claude") && oldestNoticeAge(notices) >= leadReceiverGrace {
		missing, err := s.leadReceiverMissing(project, lead)
		if err != nil {
			return err
		}
		if missing {
			if err := raiseLeadReceiverMissing(ctx, db, project, lead.Agent); err != nil {
				return err
			}
			if notices, err = db.UndeliveredNotices(ctx, project.ID); err != nil {
				return err
			}
			delivery = config.NoticeDeliveryPrompt
		}
	}
	s.dispatchNoticeCommand(ctx, db, project, notices)
	// Lead watch plugins acknowledge these without involving the Lead. Do
	// not display a Herdr notification for a batch that needs no turn.
	if found && lead.Agent != "" && extensionOwnsNotices(delivery) {
		home, err := s.homePath()
		if err != nil {
			return err
		}
		cfg, err := config.Load(home, project.Name)
		if err != nil {
			return configError(err)
		}
		if cfg.Lowkey.Lead && onlyQuietPiNotices(notices) {
			return nil
		}
	}
	if lastNotification == 0 || time.Since(time.UnixMilli(lastNotification)) >= 20*time.Second {
		_, notifyErr := s.herdrCall(ctx, "notification.show", map[string]any{"title": fmt.Sprintf("Posse: %d new notices", len(notices)), "body": project.Name})
		if notifyErr != nil {
			return notifyErr
		}
		if err := db.RecordNoticeNotification(ctx, project.ID, currentTime()); err != nil {
			return err
		}
		if project.HerdrWorkspaceID != "" {
			if _, err := s.herdrCall(ctx, "workspace.report_metadata", map[string]any{"workspace_id": project.HerdrWorkspaceID, "source": "posse", "tokens": map[string]string{"posse": fmt.Sprint(len(notices))}}); err != nil {
				return err
			}
		}
	}
	if !found || lead.Agent == "" {
		return nil
	}

