+		tasks      []store.Task
+		wantParked bool
+	}{
+		{name: "during grace", now: started.Add(grace - time.Millisecond)},
+		{name: "active Worker", now: started.Add(grace), tasks: []store.Task{{State: store.StateWorking}}},
